function systemBodies(s){const names=new Set(stationRecords(s).map(b=>b.name));const bodies=s.worlds.filter(n=>!names.has(n)&&DATA.worlds[n]?.bodyType!=='Moon').map((name,i)=>({name,index:i+1,type:DATA.worlds[name]?.bodyType||siteType(name),parent:DATA.worlds[name]?.parent,tint:DATA.worlds[name]?.tint||worldColors[name]||['#c3ad8b','#99b9c9','#b7a0cb'][i%3],slot:DATA.worlds[name]?.orbitalPosition,diagramSlot:DATA.worlds[name]?.diagramSlot,appearance:DATA.worlds[name]?.appearance,size:DATA.worlds[name]?.size}));return [...bodies,...moonRecords(s).filter(b=>b.inhabited===true)];}
